hdr = '''const READ = { '1-powersync-b': 'นักพัฒนายังต้องเขียนรายการแต่ละตารางที่เกี่ยวข้องเป็นคำสั่งสืบค้นของตัวเองในขอบเขต', '2a1': 'ผู้ใช้รายงานว่าหลังอัปเดตโปรโตคอล ไคลเอนต์รุ่นเก่าซิงก์ไม่ได้จนกว่าจะอัปเดตด้วยมือ', '3b2': 'Delta Chat บอกด้วยถ้อยคำของตัวเองว่ารีเลย์เรียบง่ายโดยการออกแบบ แต่โครงการก็ยังระบุคุณสมบัติของรีเลย์ (ส่งทันที การแจ้งเตือน การเข้ารหัสที่บังคับ) นี่คือการตีความของเรา', '4a': 'แม้ปรับแต่งมา 3 ปี การซิงก์ครั้งแรกยังใช้ 55 นาที นี่คือความเห็นของเรา', '6-electric-joining-b': 'โพสต์ยืนยันว่าโค้ดจะยังเป็นโอเพนซอร์ส แต่ไม่ได้บอกว่าใครจะดูแล' };
'''
marker="const USED = { claims: [], logos: [] };"
assert s.count(marker)==1; s=s.replace(marker,hdr+marker)
# ERPL: Thai versions of F.erpLines (built from the same facts)
erpl='''  const ERPL = [`E1 ทุกตารางในพจนานุกรมสด: กฎเดิมกับแผนตรงกัน — N=${F.erpN}, แชร์ ${F.erpSharedE1} = ${F.erpSharedE1}, ต่างกัน ${F.erpDiffer}`, `E1 ทุกหน้าต่าง AD: จำนวนตารางที่แชร์เท่ากัน — N=${F.erpWindows}, ต่างกัน 0`, 'E3 ไม่มีแผน: ไม่แชร์อะไรเลย และมีบรรทัดแจ้งให้เห็น', 'E4 แผนที่เพิ่มหนึ่งตาราง ก็แชร์ตารางนั้น โดยไฟล์อะแดปเตอร์เหมือนเดิมทุกไบต์', `E5 แฮชในล็อกเท่ากับส่วนหัวไฟล์ (${F.erpHash12})`, `การทำพังโดยตั้งใจ: จับได้ ${F.erpMutants} จาก ${F.erpMutants} · §W-PLAN-ERP PASS judged=${F.erpJudged} fails=0 open=${F.erpOpen}`];
'''
